module multi_8bit (
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] product
);

reg [15:0] product_reg;
reg [7:0] multiplicand;
reg [3:0] counter;

always @(*) begin
    product_reg = 0;
    multiplicand = A;
    for (counter = 0; counter < 8; counter = counter + 1) begin
        if (B[counter])
            product_reg = product_reg + (multiplicand << counter);
    end
end

always @(*) begin
    product = product_reg;
end

endmodule
